def parse_names(rows):
    """Return non-empty names from an iterable of mapping objects."""
    return [row.get("name", "").strip() for row in rows if row.get("name", "").strip()]

def page_items(items, page, page_size):
    """Return a zero-based page of items."""
    if page < 0 or page_size < 1:
        raise ValueError("page must be non-negative and page_size must be positive")
    start = page * page_size
    return items[start:start + page_size]
